import{j as e}from"./blog-pages-Cba4hDr6.js";import{M as i}from"./MethodCoursePage-AHwwCk6l.js";const a={slug:"tofd-training-certification-course",seoTitle:"TOFD Training and Certification Course — Time-of-Flight Diffraction | Atlantis NDT",seoDescription:"TOFD training and certification course: time-of-flight diffraction for precision weld flaw depth-sizing. Builds on UT/PAUT Level II. Online + on-site + hybrid delivery. Free consultation.",keywords:"TOFD training and certification course, time of flight diffraction training, TOFD certification, TOFD course, TOFD weld inspection",h1:"TOFD Training & Certification Course",badgeLabel:"Time-of-Flight Diffraction Qualification",heroSubtitle:"Time-of-Flight Diffraction (TOFD) training — precision depth-sizing of planar weld flaws, probe-pair configuration, and the combined TOFD+PAUT technique used on pipeline and pressure-vessel welds.",methodName:"Time-of-Flight Diffraction (TOFD)",levelLabel:"Method-specific practical qualification",hoursLabel:"TOFD is typically taken as a method-specific practical qualification layered onto an existing UT or PAUT Level II certification, rather than a standalone Level I–III track.",stats:[{label:"Qualification Type",value:"Method-Specific"},{label:"Typical Base",value:"UT/PAUT Level II"},{label:"Recert Cycle",value:"5 Years"},{label:"Delivery",value:"Online + On-site"}],overview:["Time-of-Flight Diffraction (TOFD) is an ultrasonic technique that detects and sizes flaws by measuring diffracted signals from the tips of a crack or planar discontinuity, rather than relying on the reflected signal a conventional UT beam produces. A pair of probes — one transmitter, one receiver — is positioned symmetrically across the weld, and the arrival time of the lateral wave, the back-wall echo, and any diffracted signals is used to calculate flaw depth with a precision conventional pulse-echo UT struggles to match.","Because it measures diffraction rather than reflection, TOFD is largely insensitive to flaw orientation — a real advantage for the tight-tolerance, orientation-variable cracking found in girth welds and pressure-vessel seams. In practice, TOFD is most often deployed alongside PAUT: PAUT provides volumetric weld coverage and imaging, and TOFD adds the precise depth-sizing that governs fitness-for-service and repair decisions.","This TOFD training and certification course assumes a UT or PAUT Level II foundation and focuses on the technique's specific requirements: probe-pair configuration and PCS (probe centre spacing) calculation, lateral-wave and back-wall echo identification, D-scan interpretation, and combined TOFD+PAUT scan-plan development per ASME Section V Article 4 and API 1104."],highlightTitle:"Why TOFD for Depth-Sizing",highlightBody:"Pulse-echo UT sizes a flaw by amplitude, which is sensitive to flaw orientation and can under- or over-estimate depth. TOFD sizes by diffraction arrival time, which is far less orientation-dependent — making it the technique of choice wherever accurate flaw depth genuinely drives a fitness-for-service or repair decision.",curriculum:["Diffraction physics — crack-tip diffraction vs pulse-echo reflection","Probe pair setup and PCS (probe centre spacing) calculation","Lateral wave and back-wall echo identification","D-scan interpretation and depth-sizing accuracy","Scan plan development for weld geometry and thickness","Combined TOFD+PAUT technique for pipeline girth welds","Dead-zone limitations near the surface and mitigation technique","Code requirements per ASME Section V Article 4 and API 1104","Data recording, encoded scans and report writing"],pathwaySteps:[{title:"Confirm UT/PAUT prerequisite",detail:"TOFD builds on a conventional UT or PAUT Level II foundation — enrollment assumes that base certification or documented equivalent experience."},{title:"TOFD-specific theory",detail:"Online modules on diffraction physics, probe-pair geometry, PCS calculation and D-scan interpretation."},{title:"On-site practical",detail:"Hands-on probe-pair setup, scan-plan execution and depth-sizing practice on weld samples with known, verified flaws."},{title:"Practical demonstration",detail:"Demonstrate scan-plan development and accurate flaw depth-sizing per your employer's written practice or accredited scheme requirements."},{title:"Documented on your certification record",detail:"TOFD qualification is recorded as a method-specific addition alongside your base UT/PAUT certification, sharing its 5-year SNT-TC-1A/CP-189 recertification cycle."}],faqs:[{question:"Is TOFD a separate Level I/II/III certification like UT or MT?",answer:"In practice, most schemes and employers treat TOFD as a method-specific practical qualification added on top of an existing UT or PAUT Level II certification, rather than a fully independent Level I–III track. The theory and practical requirements are still formally documented, just layered on your existing base qualification."},{question:"Why is TOFD usually paired with PAUT?",answer:"PAUT gives you volumetric coverage and a real-time cross-sectional image of the weld; TOFD gives you precise flaw-depth measurement by diffraction rather than amplitude. Used together — often called TOFD+PAUT zonal discretization — you get both good detection coverage and defensible sizing data, which is why the combination shows up so often in pipeline and pressure-vessel weld specifications."},{question:"What are the limitations of TOFD?",answer:"TOFD has a 'dead zone' near the surface where the lateral wave and near-surface signals can mask small flaws, and it typically requires a companion technique (PAUT, MT, or PT) for near-surface and surface-breaking defects. Interpreting the D-scan display also takes real practice — that's a core focus of the practical portion of this course."},{question:"Do I need conventional UT before taking TOFD?",answer:"Yes, in the sense that TOFD training assumes a working UT (or PAUT) foundation — probe theory, beam behavior, and calibration concepts carry over directly, and the course builds the diffraction-specific layer on top rather than re-teaching ultrasonic fundamentals."},{question:"How is TOFD delivered — online or in person?",answer:"Diffraction theory and D-scan interpretation are taught online. Probe-pair setup, PCS calibration and depth-sizing practice require hands-on equipment time on real weld samples, so the practical component is delivered on-site or blended."}],relatedLinks:[{to:"/paut-level-2-training-course",label:"PAUT Level 2 Training Course",desc:"Volumetric weld coverage — commonly paired with TOFD"},{to:"/asnt-level-2-ut-online-course",label:"ASNT Level 2 UT Online Course",desc:"Conventional UT foundation"},{to:"/asnt-certification",label:"ASNT Certification Guide",desc:"Full Level I/II/III pathway across all methods"}],courseName:"TOFD (Time-of-Flight Diffraction) Certification Course",courseDescription:"TOFD training covering probe-pair configuration, PCS calculation, lateral wave and back-wall echo interpretation, depth-sizing of planar flaws, and combined TOFD+PAUT weld-inspection technique.",courseTeaches:"TOFD principle of operation, probe pair configuration and PCS calculation, lateral wave and back-wall echo interpretation, depth sizing of planar flaws, and combined TOFD+PAUT zonal weld-inspection technique",coursePrerequisites:"UT Level II (or PAUT Level II) certification, or documented equivalent experience",educationalCredentialAwarded:"TOFD method-specific practical qualification, documented on base UT/PAUT certification record",educationalLevel:"Professional",articleHeadline:"TOFD Training and Certification Course: Pathway, Curriculum & Use With PAUT",articleDescription:"What TOFD training covers, why it's typically paired with PAUT, the UT/PAUT prerequisite, and how the certification pathway and 5-year recert cycle work.",articleSection:"NDT Training",articleKeywords:"TOFD training, time of flight diffraction, TOFD certification, weld depth sizing"};function r(){return e.jsx(i,{data:a})}export{r as default};
